const tubingMaterialLabels: Readonly<Record<string, string>> = {
  "Polyvinyl Chloride Tubing (PVC)": "पॉलीविनाइल क्लोराइड ट्यूब (PVC)",
  "Polyether Ether Ketone Tubing (PEEK)": "पॉलीईथर ईथर कीटोन ट्यूब (PEEK)",
  "Fluorinated Ethylene Propylene Tubing (FEP)": "फ्लोरीनीकृत एथिलीन प्रोपिलीन ट्यूब (FEP)",
  "Thermoplastic Polyurethane Tubing (TPU)": "थर्मोप्लास्टिक पॉलीयूरेथेन ट्यूब (TPU)",
  "Polytetrafluoroethylene Tubing (PTFE)": "पॉलीटेट्राफ्लोरोएथिलीन ट्यूब (PTFE)",
  "Perfluoroalkoxy Polymer Tubing (PFA)": "परफ्लोरोएल्कॉक्सी पॉलिमर ट्यूब (PFA)",
};

export function hindiProductSelectionLabel(value: string) {
  if (tubingMaterialLabels[value]) return tubingMaterialLabels[value];
  if (value === "Tube Inner Diameter") return "ट्यूब का आंतरिक व्यास";
  const luerCard = /^(.+Luer.+)\s+Fits (\d+(?:\.\d+)? mm) ID tubing\s+(PA|PP|PVDF|POM) material$/.exec(value.trim());
  if (luerCard && labels[luerCard[1]]) {
    return labels[luerCard[1]] + "\n" + luerCard[2] + " आंतरिक व्यास वाली ट्यूब के लिए\n" + luerCard[3] + " सामग्री";
  }
  const femaleAdapterCard = /^([23])-Way (M6|1\/4-28 UNF) Female Thread Adapter\s+Flow Path Diameter: ([\d.]+ mm)\s+(AC|PP|PPS) material$/.exec(value.trim());
  if (femaleAdapterCard) {
    const [, ways, thread, bore, material] = femaleAdapterCard;
    return thread + " का " + ways + "-मार्ग वाला आंतरिक थ्रेड एडाप्टर\nद्रव पथ का व्यास: " + bore + "\nसामग्री: " + material;
  }
  if (value === "Tube I.D. or Thread") return "ट्यूब का आंतरिक व्यास या थ्रेड";
  const quickCard = value.match(/^(Male|Female) (In-line|Elbow) (Valved|Non-Valved) Quick-Connect Fitting\s+(Tube I\.D\.|Thread): (.+?)\s+(POM|PP) housing \| (Panel Mount|Non-Panel Mount)$/);
  if (quickCard) {
    const [, role, shape, valve, connection, size, material, panel] = quickCard;
    const roleText = role === "Male" ? "मेल" : "फ़ीमेल";
    const shapeText = shape === "Elbow" ? "एल्बो" : "सीधी";
    const valveText = valve === "Valved" ? "वाल्व वाली" : "बिना वाल्व की";
    const connectionText = connection === "Thread" ? "थ्रेड" : "ट्यूब का आंतरिक व्यास";
    const panelText = panel === "Panel Mount" ? "पैनल-माउंट" : "इनलाइन";
    return `${roleText} सिरा, ${valveText} ${shapeText} क्विक-कनेक्ट फिटिंग\n${connectionText}: ${size}\n${material} हाउसिंग | ${panelText}`;
  }
  const bulkheadCard = value.match(/^Bulkhead Barbed Fitting\s+1\/4-28 UNF thread, (PP|PA) housing\s+For ([\d.]+ mm) tube ID$/);
  if (bulkheadCard) {
    const [, material, bore] = bulkheadCard;
    return `बल्कहेड होज़ बार्ब फिटिंग\n1/4-28 UNF थ्रेड, ${material} हाउसिंग\n${bore} आंतरिक व्यास वाली ट्यूब के लिए`;
  }
  const bulkheadAlt = value.match(/^([\d.]+ mm) tube ID, (PP|PA) (natural|white) bulkhead barbed fitting, 1\/4-28 UNF thread \((PMB-[A-Z0-9-]+)\)$/);
  if (bulkheadAlt) {
    const [, bore, material, color, model] = bulkheadAlt;
    return `${model}, 1/4-28 UNF थ्रेड वाली बल्कहेड होज़ बार्ब फिटिंग, ${bore} ट्यूब आंतरिक व्यास, ${material}, ${color === "natural" ? "प्राकृतिक रंग" : "सफ़ेद"}`;
  }
  const filterCard = value.match(/^HDPE Mesh Filter\s+Filtration Rating: ([\d–]+ μm); Housing Material: PP\s+Fits ([\d.]+ mm) ID tubing$/);
  if (filterCard) {
    const [, rating, bore] = filterCard;
    return `HDPE जाली वाला फ़िल्टर\nफ़िल्ट्रेशन रेटिंग: ${rating}, हाउसिंग: PP\n${bore} आंतरिक व्यास वाली ट्यूब के लिए`;
  }
  if (/^Diaphragm Check Valve\s+Diaphragm Material: EPDM; Housing Material: PP\s+Fits 3\.2 mm ID tubing$/.test(value)) {
    return "डायफ्राम चेक वाल्व\nडायफ्राम: EPDM, हाउसिंग: PP\n3.2 mm आंतरिक व्यास वाली ट्यूब के लिए";
  }
  const threadedCard = value.match(/^(Straight|Elbow|Short Straight|Swivel) (Thread-Seal|Bottom-Seal) Thread to Barb Fitting\s+Fits (.+?) to ([\d.]+ mm) ID tubing\s+(PP|PA|PVDF|POM|PEEK) material$/);
  if (threadedCard) {
    const [, shape, seal, thread, id, material] = threadedCard;
    const shapeText = ({ Straight: "सीधी", Elbow: "एल्बो", "Short Straight": "छोटी सीधी", Swivel: "घूमने वाली" } as Record<string, string>)[shape];
    const sealText = seal === "Thread-Seal" ? "थ्रेड पर सील" : "तली पर सील";
    return `${sealText} वाली ${shapeText} होज़ बार्ब फिटिंग\n${thread} से ${id} आंतरिक व्यास वाली ट्यूब\n${material} सामग्री`;
  }
  const threadedAlt = value.match(/^([\d.]+ mm) tube ID, (PP|PA|PVDF|POM|PEEK) (natural|white|black) (straight|elbow|swivel straight) (male|female)-thread-to-barb fitting, (.+?) thread \(((?:SA|SAL|SB|SBR|SBS|SC)-[A-Z0-9/-]+)\)$/);
  if (threadedAlt) {
    const [, size, material, color, shape, end, thread, model] = threadedAlt;
    const shapeText = shape === "elbow" ? "एल्बो" : shape === "swivel straight" ? "घूमने वाली सीधी" : "सीधी";
    const endText = end === "male" ? "मेल थ्रेड" : "फ़ीमेल थ्रेड";
    const colorText = color === "natural" ? "प्राकृतिक रंग" : color === "white" ? "सफ़ेद" : "काला";
    return `${model}, ${endText} वाली ${shapeText} होज़ बार्ब फिटिंग, ${thread} थ्रेड, ट्यूब का आंतरिक व्यास ${size}, ${material}, ${colorText}`;
  }
  const straightCard = value.match(/^Straight Barbed Fitting\s+Tube ID: ([\d.]+ mm(?: \/ [\d.]+ mm)?)\s+(PP|PA|PVDF) body \| (Natural|White)$/);
  if (straightCard) {
    const [, sizes, material, color] = straightCard;
    return `सीधी होज़ बार्ब फिटिंग\nट्यूब का आंतरिक व्यास ${sizes}\n${material} बॉडी | ${labels[color]}`;
  }
  const straightAlt = value.match(/^([\d.]+(?: × [\d.]+)? mm) tube ID, (PP|PA|PVDF) (natural|white) (equal|reducing) straight barbed fitting \((BA-[A-Z0-9-]+)\)$/);
  if (straightAlt) {
    const [, sizes, material, color, fit, model] = straightAlt;
    return `${model}, ${fit === "equal" ? "समान आकार की" : "रिड्यूसिंग"} सीधी होज़ बार्ब फिटिंग, ट्यूब का आंतरिक व्यास ${sizes}, ${material}, ${color === "natural" ? "प्राकृतिक रंग" : "सफ़ेद"}`;
  }
  return labels[value] ?? value
    .replace(/Sealing method: /g, "सीलिंग का तरीका: ")
    .replace(/Flange gasket bottom seal/g, "फ़्लैंज गैस्केट से समतल तल पर सील")
    .replace(/\bThread: /g, "थ्रेड: ")
    .replace(/\bTube OD: /g, "ट्यूब का बाहरी व्यास: ")
    .replace(/（ID）/g, " (आंतरिक व्यास)");
}

